# Turns the researcher agent's reply into a completed job.
#
# THE EXTRACTION IS THE POINT OF THIS BLOCK. The agent does not answer with
# bare JSON: Task 4's smoke test captured ~4.4k characters of which the first
# ~1000 were narration ("I'll research Linear simultaneously...") followed by a
# prose summary and only then a ```json fenced object. Stripping fences is not
# enough because prose precedes the fence. Handing that blob to
# complete_research_job would trip its payload validation and surface as a
# confusing Postgres error instead of a clear one, so the parse happens here
# and a failure to parse is reported through fail_research_job in words a
# human can act on.
#
# NOTE (code-block sandbox): only bare `except:` works -- `Exception` is not a
# defined name here -- and dunder attribute access is rejected at compile time.
import json
import sys
import requests

BASE = "{{BASE}}"
KEY = "{{SERVICE_KEY}}"
HEADERS = {"apikey": KEY, "Authorization": "Bearer " + KEY, "Content-Type": "application/json"}

# The agent runs web_scrape/web_search, so its reply can be large; give the
# write RPC room rather than orphaning a finished job on a client timeout.
TIMEOUT = 60
MAX_STARTS = 50


def rpc(name, payload, timeout=TIMEOUT):
    return requests.post(BASE + "/rest/v1/rpc/" + name, headers=HEADERS, json=payload, timeout=timeout)


def hand_back(job_id, message):
    try:
        rpc("fail_research_job", {"_job_id": job_id, "_error": message[:500]}, 30)
    except:
        pass


def extract_json(text):
    # First '{' to last '}' is what actually parsed in the smoke test, so that
    # is the first thing tried. The loop only matters when the narration itself
    # contains a brace, which would make the naive slice unparseable; each
    # later '{' is retried against the same final '}' until one parses.
    if not isinstance(text, str):
        return None
    end = text.rfind("}")
    if end < 0:
        return None
    start = text.find("{")
    tried = 0
    while start >= 0 and start < end and tried < MAX_STARTS:
        try:
            candidate = json.loads(text[start:end + 1])
            if isinstance(candidate, dict):
                return candidate
        except:
            pass
        tried = tried + 1
        start = text.find("{", start + 1)
    return None


claim = (input_data.get("Claim") or {}).get("output") or {}
job_id = claim.get("job_id") or ""
research = input_data.get("Research") or {}
answer = research.get("output")
block_error = research.get("error")

if job_id == "":
    # Unreachable while the HasJob condition gates this chain, but a job id is
    # the only thing that makes the calls below safe, so never assume one.
    output = {"ok": False, "job_id": "", "people_scored": 0, "note": "no claimed job; nothing to record"}
elif block_error:
    hand_back(job_id, "agent block failed: " + str(block_error)[:300])
    output = {"ok": False, "job_id": job_id, "people_scored": 0, "note": "agent block failed"}
else:
    payload = extract_json(answer)
    if payload is None:
        hand_back(job_id, "agent returned no parseable JSON object. First 300 characters of the reply: "
                  + str(answer)[:300])
        output = {"ok": False, "job_id": job_id, "people_scored": 0,
                  "note": "no parseable JSON in the agent reply"}
    else:
        try:
            resp = rpc("complete_research_job", {"_job_id": job_id, "_payload": payload})
            if resp.status_code >= 300:
                # complete_research_job RAISES on a malformed payload, which
                # PostgREST surfaces as a 4xx. That is a real failure: hand the
                # job back so it retries or gives up at three attempts.
                hand_back(job_id, "complete_research_job rejected the payload: HTTP %s %s"
                          % (resp.status_code, resp.text[:300]))
                output = {"ok": False, "job_id": job_id, "people_scored": 0,
                          "note": "complete rejected: HTTP %s" % resp.status_code}
            else:
                body = resp.json()
                if isinstance(body, dict) and body.get("ok"):
                    output = {"ok": True, "job_id": job_id,
                              "people_scored": body.get("people_scored") or 0, "note": ""}
                else:
                    # ok:false is the status guard, not an error: the job was
                    # not `running` any more, i.e. someone else already
                    # finished it (or the sweep requeued this slow run and
                    # another tick took it). Failing it here would flip
                    # finished work backwards, so this is deliberately a no-op.
                    output = {"ok": False, "job_id": job_id, "people_scored": 0,
                              "note": "no-op: " + json.dumps(body)[:200]}
        except:
            hand_back(job_id, "worker error while completing: " + str(sys.exc_info()[1])[:300])
            output = {"ok": False, "job_id": job_id, "people_scored": 0, "note": "complete raised"}
